package io.invenlio.procurement;import io.swagger.v3.oas.annotations.Operation;import io.swagger.v3.oas.annotations.security.SecurityRequirement;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import java.util.*;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/v1")@SecurityRequirement(name="bearerAuth")class ProcurementController{private final ProcurementService service;ProcurementController(ProcurementService s){service=s;}
 @Operation(summary="Create a tenant supplier")@PostMapping("/suppliers")ProcurementService.Supplier create(@Valid@RequestBody SupplierRequest r){return service.supplierCreate(r.command());}@Operation(summary="List suppliers with bounded filters and safe sorting")@GetMapping("/suppliers")List<ProcurementService.Supplier>list(@RequestParam(required=false)String q,@RequestParam(required=false)String status,@RequestParam(required=false)String countryCode,@RequestParam(required=false)String supplierNumber,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size,@RequestParam(required=false)String sort){return service.suppliers(q,status,countryCode,supplierNumber,page,size,sort);}@GetMapping("/suppliers/{id}")ProcurementService.Supplier detail(@PathVariable UUID id){return service.detail(id);}@PatchMapping("/suppliers/{id}")ProcurementService.Supplier update(@PathVariable UUID id,@Valid@RequestBody SupplierRequest r){return service.supplierUpdate(id,r.command(),r.version);}@PostMapping("/suppliers/{id}/{action:activate|deactivate|block|unblock|archive}")ProcurementService.Supplier lifecycle(@PathVariable UUID id,@PathVariable String action,@RequestBody Version r){return service.transition(id,action,r.version);}
 @PostMapping("/suppliers/{id}/addresses")ProcurementService.Address addressCreate(@PathVariable UUID id,@Valid@RequestBody AddressRequest r){return service.addressCreate(id,r.command());}@PatchMapping("/supplier-addresses/{id}")ProcurementService.Address addressUpdate(@PathVariable UUID id,@Valid@RequestBody AddressRequest r){return service.addressUpdate(id,r.command(),r.version);}@PostMapping("/supplier-addresses/{id}/primary")ProcurementService.Address addressPrimary(@PathVariable UUID id,@RequestBody Version r){return service.addressPrimary(id,r.version);}@PostMapping("/supplier-addresses/{id}/archive")ProcurementService.Address addressArchive(@PathVariable UUID id,@RequestBody Version r){return service.addressArchive(id,r.version);}
 @PostMapping("/suppliers/{id}/contacts")ProcurementService.Contact contactCreate(@PathVariable UUID id,@Valid@RequestBody ContactRequest r){return service.contactCreate(id,r.command());}@PatchMapping("/supplier-contacts/{id}")ProcurementService.Contact contactUpdate(@PathVariable UUID id,@Valid@RequestBody ContactRequest r){return service.contactUpdate(id,r.command(),r.version);}@PostMapping("/supplier-contacts/{id}/primary")ProcurementService.Contact contactPrimary(@PathVariable UUID id,@RequestBody Version r){return service.contactPrimary(id,r.version);}@PostMapping("/supplier-contacts/{id}/deactivate")ProcurementService.Contact contactDeactivate(@PathVariable UUID id,@RequestBody Version r){return service.contactDeactivate(id,r.version);}
 @PostMapping("/suppliers/{id}/products")ProcurementService.SupplierProduct productCreate(@PathVariable UUID id,@Valid@RequestBody ProductRequest r){return service.productCreate(id,r.command());}@GetMapping("/supplier-products/{id}")ProcurementService.SupplierProduct product(@PathVariable UUID id){return service.productDetail(id);}@PatchMapping("/supplier-products/{id}")ProcurementService.SupplierProduct productUpdate(@PathVariable UUID id,@Valid@RequestBody ProductRequest r){return service.productUpdate(id,r.command(),r.version);}@PostMapping("/supplier-products/{id}/prefer")ProcurementService.SupplierProduct prefer(@PathVariable UUID id,@RequestBody Version r){return service.prefer(id,r.version);}@PostMapping("/supplier-products/{id}/deactivate")ProcurementService.SupplierProduct deactivate(@PathVariable UUID id,@RequestBody Version r){return service.productDeactivate(id,r.version);}@GetMapping("/supplier-products")List<ProcurementService.SupplierProduct>products(@RequestParam(required=false)UUID supplierId,@RequestParam(required=false)UUID variantId,@RequestParam(required=false)Boolean active,@RequestParam(required=false)Boolean preferred,@RequestParam(required=false)String supplierSku,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size,@RequestParam(required=false)String sort){return service.products(supplierId,variantId,active,preferred,supplierSku,page,size,sort);}@GetMapping("/supplier-products/lookup")ProcurementService.SupplierProduct lookup(@RequestParam UUID supplierId,@RequestParam String supplierSku){return service.lookup(supplierId,supplierSku);}
 record Version(@PositiveOrZero long version){}record SupplierRequest(@NotBlank String supplierNumber,@NotBlank String name,String legalName,String taxId,String taxCountryCode,String registrationNumber,String email,String phone,String website,@NotBlank String defaultCurrency,Integer paymentTermsDays,Integer defaultLeadTimeDays,String notes,@PositiveOrZero long version){ProcurementService.SupplierCommand command(){return new ProcurementService.SupplierCommand(supplierNumber,name,legalName,taxId,taxCountryCode,registrationNumber,email,phone,website,defaultCurrency,paymentTermsDays,defaultLeadTimeDays,notes);}}record AddressRequest(@NotBlank String type,String label,@NotBlank String addressLine1,String addressLine2,@NotBlank String postalCode,@NotBlank String city,String stateRegion,@NotBlank String countryCode,@PositiveOrZero long version){ProcurementService.AddressCommand command(){return new ProcurementService.AddressCommand(type,label,addressLine1,addressLine2,postalCode,city,stateRegion,countryCode);}}record ContactRequest(@NotBlank String firstName,@NotBlank String lastName,String jobTitle,String email,String phone,@NotBlank String role,@PositiveOrZero long version){ProcurementService.ContactCommand command(){return new ProcurementService.ContactCommand(firstName,lastName,jobTitle,email,phone,role);}}record ProductRequest(@NotNull UUID variantId,@NotBlank String supplierSku,String supplierProductName,@NotBlank String purchaseUnitCode,@NotBlank String baseUnitsPerPurchaseUnit,String minimumOrderQuantity,String orderMultiple,String unitCost,@NotBlank String currency,Integer leadTimeDays,@PositiveOrZero long version){ProcurementService.ProductCommand command(){return new ProcurementService.ProductCommand(variantId,supplierSku,supplierProductName,purchaseUnitCode,baseUnitsPerPurchaseUnit,minimumOrderQuantity,orderMultiple,unitCost,currency,leadTimeDays);}}
}
